UPDATE ADMIN_USER
SET PASSWORD = #{password},
    PASSWORD_RESET_REQUIRED = #{resetRequired}
WHERE ADMIN_NUM = #{adminNum}

UPDATE ADMIN_USER
SET USE_YN = #{useYn}
WHERE ADMIN_NUM = #{adminNum}

UPDATE ADMIN_USER
SET DISPLAY_NAME = #{displayName}
WHERE ADMIN_NUM = #{adminNum}

UPDATE ADMIN_USER
   SET LAST_SEEN_ORDER_NUM = #{orderNum}
 WHERE ADMIN_NUM = #{adminNum}
   AND (LAST_SEEN_ORDER_NUM IS NULL OR LAST_SEEN_ORDER_NUM < #{orderNum})

UPDATE ADMIN_USER
   SET LAST_SEEN_ORDER_NUM = #{orderNum}
 WHERE ADMIN_NUM = #{adminNum}
   AND LAST_SEEN_ORDER_NUM IS NULL
